import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CAKCj7G0.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/Redis/命令.md","filePath":"数据库/Redis/命令.md","lastUpdated":1767195531000}'),r={name:"数据库/Redis/命令.md"};function a(h,t,n,u,i,s){return e(),o("div",null,[...t[0]||(t[0]=[c('<h2 id="通用命令" tabindex="-1">通用命令 <a class="header-anchor" href="#通用命令" aria-label="Permalink to &quot;通用命令&quot;">​</a></h2><p>通用命令不依赖具体数据结构，主要用于键的基础管理、过期设置、查询等操作。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>KEYS pattern</code></td><td>匹配符合规则的所有键（慎用，阻塞主线程）</td><td><code>KEYS user*</code> → 匹配所有以 <code>user</code> 开头的键</td></tr><tr><td><code>EXISTS key</code></td><td>判断键是否存在（返回 1 存在，0 不存在）</td><td><code>EXISTS name</code> → 1</td></tr><tr><td><code>DEL key [key...]</code></td><td>删除一个/多个键</td><td><code>DEL name age</code> → 删除 name 和 age 键</td></tr><tr><td><code>EXPIRE key seconds</code></td><td>设置键的过期时间（秒）</td><td><code>EXPIRE code 60</code> → code 60 秒后过期</td></tr><tr><td><code>TTL key</code></td><td>查看键的剩余过期时间（-1 永不过期，-2 已过期）</td><td><code>TTL code</code> → 50（剩余 50 秒）</td></tr><tr><td><code>PERSIST key</code></td><td>移除键的过期时间（变为永不过期）</td><td><code>PERSIST code</code> → 1（成功）</td></tr><tr><td><code>TYPE key</code></td><td>查看键对应的值类型</td><td><code>TYPE name</code> → string</td></tr><tr><td><code>RENAMENX key newkey</code></td><td>仅当新键不存在时重命名</td><td><code>RENAMENX name username</code> → 1（成功）</td></tr><tr><td><code>SCAN cursor [MATCH pattern] [COUNT count]</code></td><td>渐进式遍历键（替代KEYS，非阻塞）</td><td><code>SCAN 0 MATCH user* COUNT 10</code> → 遍历user开头的键</td></tr><tr><td><code>FLUSHDB</code></td><td>清空当前数据库（慎用）</td><td><code>FLUSHDB</code> → 清空当前库所有键</td></tr></tbody></table><hr><h2 id="字符串-string-命令" tabindex="-1">字符串（String）命令 <a class="header-anchor" href="#字符串-string-命令" aria-label="Permalink to &quot;字符串（String）命令&quot;">​</a></h2><p>String 是 Redis 最基础的数据类型，可存储字符串、数字（整数/浮点数），常用于缓存单个值（如用户信息、计数器）。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>SET key value</code></td><td>设置键值对（覆盖已有值）</td><td><code>SET name &quot;zhangsan&quot;</code> → OK</td></tr><tr><td><code>SETNX key value</code></td><td>仅当键不存在时设置（分布式锁常用）</td><td><code>SETNX lock 1</code> → 1（设置成功）</td></tr><tr><td><code>GET key</code></td><td>获取键对应的值</td><td><code>GET name</code> → &quot;zhangsan&quot;</td></tr><tr><td><code>INCR key</code></td><td>键值为数字时，自增 1（原子操作）</td><td><code>INCR count</code> → 1（count 初始为 0）</td></tr><tr><td><code>INCRBY key num</code></td><td>自增指定数值</td><td><code>INCRBY count 5</code> → 6</td></tr><tr><td><code>DECR key</code></td><td>键值为数字时，自减 1（原子操作）</td><td><code>DECR count</code> → 5</td></tr><tr><td><code>APPEND key value</code></td><td>向字符串末尾追加内容</td><td><code>APPEND name &quot; - 18&quot;</code> → &quot;zhangsan - 18&quot;</td></tr><tr><td><code>GETRANGE key start end</code></td><td>获取字符串指定区间的子串</td><td><code>GETRANGE name 0 5</code> → &quot;zhang&quot;</td></tr></tbody></table><hr><h2 id="哈希-hash-命令" tabindex="-1">哈希（Hash）命令 <a class="header-anchor" href="#哈希-hash-命令" aria-label="Permalink to &quot;哈希（Hash）命令&quot;">​</a></h2><p>Hash 用于存储<strong>键值对的集合</strong>（类似 JSON 对象），适合存储结构化数据（如用户信息：id、name、age），相比 String 更节省内存，且支持单独修改某个字段。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>HSET key field value</code></td><td>设置哈希的字段和值</td><td><code>HSET user:1 name &quot;lisi&quot; age 20</code> → 2（设置了 2 个字段）</td></tr><tr><td><code>HGET key field</code></td><td>获取哈希指定字段的值</td><td><code>HGET user:1 name</code> → &quot;lisi&quot;</td></tr><tr><td><code>HMSET key f1 v1 f2 v2</code></td><td>批量设置哈希字段（Redis 4.0+ 可用 HSET 替代）</td><td><code>HMSET user:2 name &quot;wangwu&quot; age 25</code> → OK</td></tr><tr><td><code>HMGET key f1 f2</code></td><td>批量获取哈希字段的值</td><td><code>HMGET user:2 name age</code> → [&quot;wangwu&quot;, &quot;25&quot;]</td></tr><tr><td><code>HGETALL key</code></td><td>获取哈希所有字段和值（返回键值对列表）</td><td><code>HGETALL user:1</code> → [&quot;name&quot;,&quot;lisi&quot;,&quot;age&quot;,&quot;20&quot;]</td></tr><tr><td><code>HDEL key field [field...]</code></td><td>删除哈希指定字段</td><td><code>HDEL user:1 age</code> → 1（删除成功）</td></tr><tr><td><code>HKEYS key</code></td><td>获取哈希所有字段名</td><td><code>HKEYS user:1</code> → [&quot;name&quot;]</td></tr><tr><td><code>HVALS key</code></td><td>获取哈希所有字段值</td><td><code>HVALS user:1</code> → [&quot;lisi&quot;]</td></tr></tbody></table><hr><h2 id="列表-list-命令" tabindex="-1">列表（List）命令 <a class="header-anchor" href="#列表-list-命令" aria-label="Permalink to &quot;列表（List）命令&quot;">​</a></h2><p>List 是<strong>有序、可重复</strong>的字符串列表（底层是双向链表），适合实现消息队列、最新消息列表、分页等场景。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>LPUSH key value [value...]</code></td><td>从列表左侧（头部）添加元素</td><td><code>LPUSH msg &quot;hello&quot; &quot;world&quot;</code> → 2（列表长度为 2）</td></tr><tr><td><code>RPUSH key value [value...]</code></td><td>从列表右侧（尾部）添加元素</td><td><code>RPUSH msg &quot;redis&quot;</code> → 3</td></tr><tr><td><code>LPOP key</code></td><td>从列表左侧弹出元素（删除并返回）</td><td><code>LPOP msg</code> → &quot;world&quot;</td></tr><tr><td><code>RPOP key</code></td><td>从列表右侧弹出元素</td><td><code>RPOP msg</code> → &quot;redis&quot;</td></tr><tr><td><code>BLPOP key [key...] timeout</code></td><td>阻塞式左弹出（List，队列消费）</td><td><code>BLPOP msg 0</code> → 阻塞等待消息，0表示永久</td></tr><tr><td><code>LRANGE key start end</code></td><td>获取列表指定区间的元素（0 开头，-1 表示最后一个）</td><td><code>LRANGE msg 0 -1</code> → [&quot;hello&quot;]</td></tr><tr><td><code>LLEN key</code></td><td>获取列表长度</td><td><code>LLEN msg</code> → 1</td></tr><tr><td><code>LTRIM key start end</code></td><td>裁剪列表，只保留指定区间元素</td><td><code>LTRIM msg 0 0</code> → 仅保留第一个元素</td></tr></tbody></table><hr><h2 id="集合-set-命令" tabindex="-1">集合（Set）命令 <a class="header-anchor" href="#集合-set-命令" aria-label="Permalink to &quot;集合（Set）命令&quot;">​</a></h2><p>Set 是<strong>无序、不可重复</strong>的字符串集合，支持交集、并集、差集等集合运算，适合实现标签、好友关注、去重等场景。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>SADD key member [member...]</code></td><td>向集合添加元素（重复添加无效）</td><td><code>SADD tag &quot;java&quot; &quot;python&quot; &quot;java&quot;</code> → 2</td></tr><tr><td><code>SMEMBERS key</code></td><td>获取集合所有元素</td><td><code>SMEMBERS tag</code> → [&quot;java&quot;,&quot;python&quot;]</td></tr><tr><td><code>SREM key member [member...]</code></td><td>删除集合指定元素</td><td><code>SREM tag &quot;java&quot;</code> → 1</td></tr><tr><td><code>SCARD key</code></td><td>获取集合元素个数</td><td><code>SCARD tag</code> → 1</td></tr><tr><td><code>SINTER key1 key2</code></td><td>获取多个集合的交集</td><td><code>SADD tag2 &quot;python&quot; &quot;go&quot;</code> → <code>SINTER tag tag2</code> → [&quot;python&quot;]</td></tr><tr><td><code>SUNION key1 key2</code></td><td>获取多个集合的并集</td><td><code>SUNION tag tag2</code> → [&quot;python&quot;,&quot;go&quot;]</td></tr><tr><td><code>SISMEMBER key member</code></td><td>判断元素是否在集合中</td><td><code>SISMEMBER tag &quot;python&quot;</code> → 1</td></tr></tbody></table><hr><h2 id="有序集合-sorted-set-zset-命令" tabindex="-1">有序集合（Sorted Set/ZSet）命令 <a class="header-anchor" href="#有序集合-sorted-set-zset-命令" aria-label="Permalink to &quot;有序集合（Sorted Set/ZSet）命令&quot;">​</a></h2><p>ZSet 是<strong>有序、不可重复</strong>的集合，每个元素关联一个<strong>分数（score）</strong>，按分数排序（可升序/降序），适合实现排行榜、延迟队列、权重排序等场景。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>ZADD key score member [score member...]</code></td><td>添加元素（分数为数字）</td><td><code>ZADD rank 90 &quot;zhangsan&quot; 85 &quot;lisi&quot;</code> → 2</td></tr><tr><td><code>ZRANGE key start end [WITHSCORES]</code></td><td>按分数升序获取元素（WITHSCORES 显示分数）</td><td><code>ZRANGE rank 0 -1 WITHSCORES</code> → [&quot;lisi&quot;,&quot;85&quot;,&quot;zhangsan&quot;,&quot;90&quot;]</td></tr><tr><td><code>ZREVRANGE key start end [WITHSCORES]</code></td><td>按分数降序获取元素</td><td><code>ZREVRANGE rank 0 0</code> → [&quot;zhangsan&quot;]</td></tr><tr><td><code>ZSCORE key member</code></td><td>获取元素的分数</td><td><code>ZSCORE rank &quot;zhangsan&quot;</code> → &quot;90&quot;</td></tr><tr><td><code>ZINCRBY key increment member</code></td><td>给元素的分数增加指定值</td><td><code>ZINCRBY rank 5 &quot;lisi&quot;</code> → &quot;90&quot;</td></tr><tr><td><code>ZCARD key</code></td><td>获取有序集合元素个数</td><td><code>ZCARD rank</code> → 2</td></tr></tbody></table><hr><h2 id="位图-bitmap-命令" tabindex="-1">位图（Bitmap）命令 <a class="header-anchor" href="#位图-bitmap-命令" aria-label="Permalink to &quot;位图（Bitmap）命令&quot;">​</a></h2><p>Bitmap 本质是 String 类型的扩展，按位存储（0/1），适合存储海量布尔型数据（如用户签到、在线状态），节省内存。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>SETBIT key offset value</code></td><td>设置指定偏移量的位值（0/1）</td><td><code>SETBIT sign:1 0 1</code> → 用户1 第0天签到</td></tr><tr><td><code>GETBIT key offset</code></td><td>获取指定偏移量的位值</td><td><code>GETBIT sign:1 0</code> → 1（已签到）</td></tr><tr><td><code>BITCOUNT key [start end]</code></td><td>统计指定区间内 1 的位数</td><td><code>BITCOUNT sign:1</code> → 5（5 天签到）</td></tr><tr><td><code>BITOP op destkey key1 [key2...]</code></td><td>位运算（AND/OR/XOR/NOT）</td><td><code>BITOP OR sign:all sign:1 sign:2</code> → 合并两个用户签到</td></tr></tbody></table><hr><h2 id="地理空间-geo-命令" tabindex="-1">地理空间（GEO）命令 <a class="header-anchor" href="#地理空间-geo-命令" aria-label="Permalink to &quot;地理空间（GEO）命令&quot;">​</a></h2><p>用于存储和查询地理位置信息（经纬度），适合附近的人、门店距离计算等场景。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>GEOADD key lon lat member</code></td><td>添加地理位置（经度、纬度、名称）</td><td><code>GEOADD shop 116.40 39.90 &quot;王府井&quot;</code> → 1</td></tr><tr><td><code>GEOPOS key member [member...]</code></td><td>获取指定位置的经纬度</td><td><code>GEOPOS shop 王府井</code> → [116.40, 39.90]</td></tr><tr><td><code>GEODIST key m1 m2 [unit]</code></td><td>计算两个位置的距离（unit：m/km/mi/ft）</td><td><code>GEODIST shop 王府井 西单 km</code> → 3.5（公里）</td></tr><tr><td><code>GEORADIUS key lon lat radius unit [WITHCOORD]</code></td><td>按经纬度搜索指定半径内的位置</td><td><code>GEORADIUS shop 116.40 39.90 5 km</code> → 5公里内的门店</td></tr></tbody></table><hr><h2 id="流-stream-命令" tabindex="-1">流（Stream）命令 <a class="header-anchor" href="#流-stream-命令" aria-label="Permalink to &quot;流（Stream）命令&quot;">​</a></h2><p>Redis 5.0+ 新增的消息队列结构，支持持久化、消费组、消息确认，比 List 更适合生产级消息队列。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>XADD key * field value [field value...]</code></td><td>向流添加消息（* 自动生成 ID）</td><td><code>XADD order * uid 100 amount 99</code> → 生成消息ID</td></tr><tr><td><code>XRANGE key start end [COUNT count]</code></td><td>按 ID 范围读取消息（- 最早，+ 最晚）</td><td><code>XRANGE order - + COUNT 10</code> → 读取10条消息</td></tr><tr><td><code>XGROUP CREATE key group id</code></td><td>创建消费组</td><td><code>XGROUP CREATE order g1 0</code> → 为order流创建g1消费组</td></tr><tr><td><code>XREADGROUP GROUP group consumer COUNT count STREAMS key &gt;</code></td><td>消费组读取消息（&gt; 未消费）</td><td><code>XREADGROUP GROUP g1 c1 COUNT 5 STREAMS order &gt;</code></td></tr></tbody></table><hr><h2 id="发布订阅-pub-sub-命令" tabindex="-1">发布订阅（Pub/Sub）命令 <a class="header-anchor" href="#发布订阅-pub-sub-命令" aria-label="Permalink to &quot;发布订阅（Pub/Sub）命令&quot;">​</a></h2><p>实现简单的消息发布与订阅，适合实时通知（如系统告警、消息推送）。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>SUBSCRIBE channel [channel...]</code></td><td>订阅一个/多个频道</td><td><code>SUBSCRIBE notice</code> → 订阅notice频道</td></tr><tr><td><code>PUBLISH channel message</code></td><td>向频道发布消息</td><td><code>PUBLISH notice &quot;系统升级&quot;</code> → 1（1个订阅者）</td></tr><tr><td><code>UNSUBSCRIBE [channel...]</code></td><td>取消订阅频道</td><td><code>UNSUBSCRIBE notice</code> → 取消订阅</td></tr><tr><td><code>PSUBSCRIBE pattern</code></td><td>按模式订阅频道（如 notice*）</td><td><code>PSUBSCRIBE notice*</code> → 订阅所有notice开头的频道</td></tr></tbody></table><hr><h2 id="事务与脚本命令" tabindex="-1">事务与脚本命令 <a class="header-anchor" href="#事务与脚本命令" aria-label="Permalink to &quot;事务与脚本命令&quot;">​</a></h2><p>用于实现复杂原子操作，避免并发问题。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>MULTI</code></td><td>开启事务（后续命令入队，EXEC 执行）</td><td><code>MULTI</code> → OK</td></tr><tr><td><code>EXEC</code></td><td>执行事务中的所有命令</td><td><code>EXEC</code> → 返回各命令执行结果</td></tr><tr><td><code>DISCARD</code></td><td>放弃事务（清空队列）</td><td><code>DISCARD</code> → OK</td></tr><tr><td><code>WATCH key [key...]</code></td><td>监视键，若事务执行前键被修改则事务取消</td><td><code>WATCH balance</code> → 监视余额键</td></tr><tr><td><code>EVAL script numkeys key [key...] arg [arg...]</code></td><td>执行Lua脚本（原子操作）</td><td><code>EVAL &quot;return redis.call(&#39;INCR&#39;, KEYS[1])&quot; 1 count</code> → 自增count</td></tr></tbody></table><hr><h2 id="连接管理命令" tabindex="-1">连接管理命令 <a class="header-anchor" href="#连接管理命令" aria-label="Permalink to &quot;连接管理命令&quot;">​</a></h2><h3 id="连接命令" tabindex="-1">连接命令 <a class="header-anchor" href="#连接命令" aria-label="Permalink to &quot;连接命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>AUTH password</code></td><td>认证密码（连接Redis后验证）</td><td><code>AUTH 123456</code> → OK</td></tr><tr><td><code>PING</code></td><td>测试连接是否正常（返回PONG）</td><td><code>PING</code> → PONG</td></tr><tr><td><code>SELECT db</code></td><td>切换数据库（Redis默认16个库，0-15）</td><td><code>SELECT 1</code> → 切换到1号库</td></tr><tr><td><code>QUIT</code></td><td>关闭客户端连接</td><td><code>QUIT</code> → OK</td></tr></tbody></table><h3 id="服务器状态-配置命令" tabindex="-1">服务器状态/配置命令 <a class="header-anchor" href="#服务器状态-配置命令" aria-label="Permalink to &quot;服务器状态/配置命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>INFO [section]</code></td><td>查询Redis状态信息（内存、客户端、持久化等）</td><td><code>INFO memory</code> → 查看内存使用情况</td></tr><tr><td><code>CONFIG GET param</code></td><td>获取配置参数</td><td><code>CONFIG GET requirepass</code> → 获取密码</td></tr><tr><td><code>CONFIG SET param value</code></td><td>修改配置参数（无需重启）</td><td><code>CONFIG SET maxmemory 1GB</code> → 设置最大内存</td></tr><tr><td><code>CLIENT LIST</code></td><td>查看所有客户端连接信息</td><td><code>CLIENT LIST</code> → 返回连接列表</td></tr><tr><td><code>CLIENT KILL ip:port</code></td><td>关闭指定客户端连接</td><td><code>CLIENT KILL 192.168.1.100:6000</code> → OK</td></tr></tbody></table><h3 id="持久化相关命令" tabindex="-1">持久化相关命令 <a class="header-anchor" href="#持久化相关命令" aria-label="Permalink to &quot;持久化相关命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>BGSAVE</code></td><td>后台生成RDB快照（不阻塞主线程）</td><td><code>BGSAVE</code> → Background saving started</td></tr><tr><td><code>SAVE</code></td><td>前台生成RDB快照（阻塞主线程，慎用）</td><td><code>SAVE</code> → OK</td></tr><tr><td><code>BGREWRITEAOF</code></td><td>后台重写AOF文件（压缩命令）</td><td><code>BGREWRITEAOF</code> → Background append only file rewriting started</td></tr><tr><td><code>CONFIG GET dir</code></td><td>获取RDB/AOF文件存储目录</td><td><code>CONFIG GET dir</code> → /var/lib/redis</td></tr></tbody></table><hr><h2 id="分布式相关命令" tabindex="-1">分布式相关命令 <a class="header-anchor" href="#分布式相关命令" aria-label="Permalink to &quot;分布式相关命令&quot;">​</a></h2><p>用于 Redis 主从、哨兵、集群的管理和状态查询。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>SLAVEOF host port</code></td><td>设置当前节点为从节点</td><td><code>SLAVEOF 192.168.1.2 6379</code> → OK</td></tr><tr><td><code>INFO replication</code></td><td>查看主从复制状态</td><td><code>INFO replication</code> → 显示主节点、从节点信息</td></tr><tr><td><code>CLUSTER INFO</code></td><td>查看集群状态（仅Cluster模式）</td><td><code>CLUSTER INFO</code> → 集群节点数、槽分配等</td></tr><tr><td><code>CLUSTER NODES</code></td><td>查看集群所有节点信息</td><td><code>CLUSTER NODES</code> → 节点ID、角色、槽范围</td></tr><tr><td><code>SENTINEL masters</code></td><td>查看哨兵监控的主节点列表</td><td><code>SENTINEL masters</code> → 主节点信息</td></tr></tbody></table>',55)])])}const S=d(r,[["render",a]]);export{E as __pageData,S as default};
